        "teacher_support": "Profesorul demonstreaza pe proiector, elevii executa în paralel"
      },
      {
        "task": "Salvarea rapida și verificarea",
        "steps": [
          "Adaugă o propozitie noua: 'Astazi am învățat să salvez documente.'",
          "Observa ca titlul documentului acum arată numele ales, nu 'Document1'",
          "Apasă Ctrl+S pentru salvare rapida",
          "Închide documentul (X sau File > Close)",
          "Deschide File Explorer și navigheaza la Documents - găsește fișierul!"
        ],
        "teacher_support": "Asigura-te ca fiecare elev găsește fișierul salvat"
      },
      {
        "task": "Deschiderea documentului salvat",
        "steps": [
          "În Word/Writer, click File > Open (sau Ctrl+O)",
          "Navigheaza la Documents",
          "Găsește 'Primul_meu_document.docx'",
          "Dublu-click pentru a deschide",
          "Verifică: textul este acolo!"
        ],
        "teacher_support": "Momentul 'aha!' - elevii vad ca munca lor a fost salvata"
      }
    ],
    "success_criteria": [
      "Elevul poate crea un document nou",
      "Elevul poate salva documentul cu un nume ales într-o locatie specifica",
      "Elevul poate redeschide documentul salvat"
    ]
  },
  "practice_independent": {
    "duration_minutes": 15,
    "levels": {
      "minim": [
        {
          "task": "Creează un document nou cu 3 propozitii despre tine (nume, varsta, hobby). Salvează-l în Documents cu numele 'Despre_mine'. Închide și redeschide documentul pentru a verifică.",
          "expected_output": "Document salvat și redeschis cu succes"
        }
      ],
      "standard": [
        {
          "task": "1) Creează un document cu o lista de 5 lucruri preferate. Salvează ca 'Lista_preferinte'. 2) Salvează ACELAȘI document și în format PDF folosind Save As. 3) Verifică în File Explorer ca ai 2 fișiere: unul .docx și unul .pdf.",
          "expected_output": "Doua fișiere cu același continut în formate diferite"
        }
      ],
      "performanta": [
        {
          "task": "1) Creează un folder nou în Documents numit 'Lectii_TIC'. 2) Creează un document cu un scurt rezumat al lectiei de azi. 3) Salvează-l în folderul nou creat. 4) Creează încă 2 documente goale cu nume sugestive pentru lectiile viitoare și salvează-le în același folder. 5) Fa un screenshot cu folderul și cele 3 fișiere.",
          "expected_output": "Folder organizat cu 3 documente și screenshot ca dovada"
        }
      ]
    }
  },
  "wrap_up": {
    "duration_minutes": 7,
    "exit_ticket": {
      "minim": [
        "Care este comanda rapida de tastatura pentru Save? (Ctrl+...)"
      ],
      "standard": [
        "Care e diferenta dintre Save și Save As? Când folosești fiecare?"
      ],
      "performanta": [
        "De ce este important să alegi un nume clar pentru fișier și să-l salvezi într-un folder potrivit?"
      ]
    },
    "preview_next": "Saptamana viitoare învățăm să facem textul să arate frumos - bold, italic, culori și marimi diferite!"
  }
